    ---@type ActivityMidFestivalBossComponent
    self._bossComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalBossComponent)
    ---@type PlayerComponent
    self._playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
