--region handler
function ActivityMidFestivalBossMeRankCell:OnBtnDetailHandler()
    if isNull(self._rankInfo) then
        return
    end
    local isInList = false
    for _, rank in ipairs(self._rankInfo) do
        if checkString(rank.playerId) == self._playerDojo.playerId then
            isInList = true
            GameUtils.ShowCommonTeamsTipsBoard(self.BtnDetails, rank.team, nil, nil, self._playerDojo.playerName)
        end
    end
    if not isInList then
        GameUtils.ShowCommonTeamsTipsBoard(self.BtnDetails, {{}}, '', nil, self._playerDojo.playerName)
    end
end
--endregion handler

--region public
function ActivityMidFestivalBossMeRankCell:Refresh()
    self._bossHomeDojo = self._bossComp:GetBossHomeDojo()
    self._rankInfo = self._bossHomeDojo.rankInfo
    self._myRankInfo = self._bossHomeDojo.playerRank
    self._playerDojo = self._playerComp:GetPlayerDojo()
    ---@type ActivityMidFestivalMgr
    local ActivityMidFestivalMgr = import("Game.Activity.MidFestival.ActivityMidFestivalMgr"):GetInstance()
    self._rankListVo = ActivityMidFestivalMgr:GetRankRewardList()
    ---@type MidFestivalBossParameterVo
    local parametersVo = CfUtils.GetCf(AutoIds.IdSetting6104, "MidFestivalBossParameterVo", true)[1]
    -- 排行榜最大显示的玩家数量
    self._rankShowCount = checkNumber(parametersVo.num)
    self._rankText = checkString(self._myRankInfo.ranking)
    self._outOfRankList = false
    local myRankNum = checkNumber(self._myRankInfo.ranking)
    if myRankNum > self._rankShowCount then
        self._outOfRankList = true
        self._rankText = myRankNum
        for _, vo in ipairs(self._rankListVo) do
            ---@type MidFestivalBossRankRewardVo
            local rankVo = vo
            if checkNumber(rankVo.type) == RankType.Percentage then
                if myRankNum >= checkNumber(rankVo.upperLimit) and myRankNum <= checkNumber(rankVo.lowerLimit) then
                    self._rankText = rankVo.name
                end
            end
        end
    end
    self:RefreshUI()
end
--endregion public

--region private
function ActivityMidFestivalBossMeRankCell:RefreshUI()
    -- 基本信息
    CfUtils.FillText(self.TxtName, self._playerDojo.playerName)
    CfUtils.FillText(self.TextLevel, "Lv." .. self._playerDojo.level)
    self._headScr:FreshAvatarFrame(self._playerDojo.playerAvatar, self._playerDojo.playerAvatarFrame)
    --self._headScr:SetCallBack(function()
    --    GameUtils.ShowPlayerInfo(self._playerDojo.playerId,{
    --        { id = Constants.UITypeIds.UIActivityMidFestivalBossDialog }
    --    })
    --end)

    -- 排行信息
    if string.isEmpty(checkString(self._myRankInfo.hurt)) then
        -- 未造成伤害
        CfUtils.SetActive(self.TxtNo, true)
        CfUtils.SetActive(self.RankNode, false)
    else
        CfUtils.SetUISwitchImage(self.ImgRank, checkNumber(self._myRankInfo.ranking))
        CfUtils.FillText(self.Txtranking, self._rankText)
        CfUtils.SetActive(self.TxtNo, false)
        CfUtils.SetActive(self.RankNode, true)
    end

    CfUtils.SetActive(self.ImgRank, not self._outOfRankList)

    -- 伤害和奖励
    CfUtils.FillText(self.TxtDamage, checkString(self._myRankInfo.hurt))
    local rewards = {}
    for _, rank in ipairs(self._rankListVo) do
        ---@type MidFestivalBossRankRewardVo
        local rankVo = rank
        if checkNumber(self._myRankInfo.ranking) >= rankVo.upperLimit and checkNumber(self._myRankInfo.ranking) <= rankVo.lowerLimit then
            local rewardCount = table.count(rankVo.reward)
            for i = 1, rewardCount do
                local reward = {
                    goodsId = rankVo.reward[i],
                    num = rankVo.rewardNum[i],
                }
                table.insert(rewards, reward)
            end
        end
    end
    CfUtils.SetActive(self.TextNoReward, table.count(rewards) == 0)
    self._rewardsScr:FreshBaseUI(rewards)

    CfUtils.SetActive(self.BtnDetails, not self._outOfRankList)

    CfUtils.SetActive(self.controller.gameObject, true)
end
--endregion private

